import pytest
from fastapi import APIRouter, FastAPI, Response
from fastapi.responses import JSONResponse, StreamingResponse
from fastapi.routing import APIRoute
from fastapi.testclient import TestClient

DEFAULT_HEADERS = {\"Cache-Control\": \"max-age=300\", \"X-Source\": \"db\"}


def test_default_response_headers():
    app = FastAPI()

    @app.get(\"/cached-item\", default_response_headers=DEFAULT_HEADERS)
    def cached_item():
        return {\"item\": \"cached\"}

    @app.get(\"/uncached-item\", default_response_headers=DEFAULT_HEADERS)
    def uncached_item(response: Response):
        response.headers[\"cache-control\"] = \"no-store\"
        return {\"item\": \"uncached\"}

    client = TestClient(app)
    response = client.get(\"/cached-item\")
    assert response.status_code == 200
    assert response.headers[\"Cache-Control\"] == \"max-age=300\"
    assert response.headers[\"X-Source\"] == \"db\"

    response = client.get(\"/uncached-item\")
    assert response.status_code == 200
    assert response.headers.get_list(\"Cache-Control\") == [\"no-store\"]
    assert response.headers[\"X-Source\"] == \"db\"


@pytest.mark.parametrize(\"method\", [\"get\", \"post\", \"put\", \"delete\", \"options\", \"head\", \"patch\", \"trace\", \"api_route\"])
@pytest.mark.parametrize(\"use_router\", [False, True])
def test_decorators_default_response_headers(method, use_router):
    app = FastAPI()
    router = APIRouter() if use_router else app

    @getattr(router, method)(\"/item\", default_response_headers=DEFAULT_HEADERS)
    def item():
        return {\"item\": \"cached\"}

    if use_router:
        parent = APIRouter()
        parent.include_router(router, prefix=\"/nested\")
        app.include_router(parent)
    path = \"/nested/item\" if use_router else \"/item\"
    response = TestClient(app).request(\"get\" if method == \"api_route\" else method, path)
    assert response.status_code == 200
    assert response.headers[\"Cache-Control\"] == \"max-age=300\"
    assert response.headers[\"X-Source\"] == \"db\"


@pytest.mark.parametrize(\"streaming\", [False, True])
def test_explicit_response_headers_win(streaming):
    app = FastAPI()

    @app.get(\"/item\", default_response_headers=DEFAULT_HEADERS)
